+    // ---- Save-cost spike (--save-cost <fixture dir>) ----
+    // Measures how long each kind of project write blocks the main thread.
+    // One line per measurement, prefixed "SAVECOST", for grep.
+    using Clock = std::chrono::steady_clock;
+    static double ms_between(Clock::time_point from, Clock::time_point to)
+    {
+        return std::chrono::duration<double, std::milli>(to - from).count();
+    }
+
+    struct CostFixture
+    {
+        std::string              name;
+        std::vector<std::string> files;
+        int                      plates{1};
+    };
+
+    std::vector<CostFixture> cost_fixtures() const
+    {
+        const fs::path dir(m_state->save_cost_dir);
+        auto stls = [&dir](const char* sub) {
+            std::vector<std::string> files;
+            if (fs::is_directory(dir / sub))
+                for (const fs::directory_entry& entry : fs::directory_iterator(dir / sub))
+                    if (entry.path().extension() == ".stl")
+                        files.emplace_back(entry.path().string());
+            std::sort(files.begin(), files.end());
+            return files;
+        };
+        const std::vector<CostFixture> all{
+            {"tiny", {}, 2},
+            {"typical", {std::string(JUSPRIN_SOURCE_DIR) + "/resources/handy_models/3DBenchy.drc"}, 1},
+            {"medium", stls("medium"), 2},
+            {"large", stls("large"), 1},
+            {"huge", stls("huge"), 1},
+            {"many", stls("many"), 10},
+        };
+        std::vector<CostFixture> chosen;
+        for (const CostFixture& fixture : all) {
+            const auto& wanted = m_state->save_cost_fixtures;
+            if (!wanted.empty() && std::find(wanted.begin(), wanted.end(), fixture.name) == wanted.end())
+                continue;
+            if (fixture.name != "tiny" && fixture.files.empty()) {
+                std::cerr << "SAVECOST SKIP fixture=" << fixture.name << " reason=no_files\n";
+                continue;
+            }
+            chosen.emplace_back(fixture);
+        }
+        return chosen;
+    }
+
+    void run_next_step()
+    {
+        if (m_finished)
+            return;
+        if (m_steps.empty()) {
+            finish();
+            return;
+        }
+        auto step = std::move(m_steps.front());
+        m_steps.pop_front();
+        try {
+            step([self = shared_from_this()] { self->m_app.CallAfter([self] { self->run_next_step(); }); });
+        } catch (const std::exception& error) {
+            fail(std::string("save-cost exception: ") + error.what());
+        }
+    }
+
+    // Polls on the main loop so the backup thread's UI tasks and repaints keep running.
+    void poll_until(std::function<bool()> ready, double timeout_ms, std::function<void(bool, Clock::time_point)> then)
+    {
+        const Clock::time_point start = Clock::now();
+        m_poll = std::make_unique<wxTimer>();
+        m_poll->Bind(wxEVT_TIMER, [this, ready, then, start, timeout_ms](wxTimerEvent&) {
+            const Clock::time_point now = Clock::now();
+            const bool ok = ready();
+            if (!ok && ms_between(start, now) < timeout_ms)
+                return;
+            m_poll->Stop();
+            m_app.CallAfter([then, ok, now] { then(ok, now); });
+        });
+        m_poll->Start(5);
+    }
+
+    std::string mesh_backup_file(const ModelObject& object)
+    {
+        Model& model = m_plater->model();
+        return model.get_backup_path() + "/3D/Objects/" + object.name + "_" + std::to_string(model.get_object_backup_id(object)) +
+               ".model";
+    }
+
+    static ino_t inode_of(const std::string& path)
+    {
+        struct stat info {};
+        return ::stat(path.c_str(), &info) == 0 ? info.st_ino : 0;
+    }
+
+    bool all_meshes_backed_up()
+    {
+        for (const ModelObject* object : m_plater->model().objects)
+            if (!fs::exists(mesh_backup_file(*object)))
+                return false;
+        return true;
+    }
+
+    void load_cost_fixture(const CostFixture& fixture)
+    {
+        struct DialogProbe : wxModalDialogHook {
+            int count{0};
+            int Enter(wxDialog*) override { ++count; return wxID_CANCEL; }
+        } dialogs;
+        dialogs.Register();
+        const Clock::time_point start = Clock::now();
+        PartPlateList& plates = m_plater->get_partplate_list();
+        if (fixture.name == "tiny") {
+            // The automated scenario's fixture: a cube and its duplicate, one per plate.
+            const std::string cube = std::string(JUSPRIN_SOURCE_DIR) + "/tests/data/test_stl/ASCII/20mmbox-LF.stl";
+            m_plater->load_files(std::vector<std::string>{cube},
+                                 LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence, false);
+            m_plater->duplicate_object(0);
+            const int second_plate = plates.create_plate(true);
+            plates.add_to_plate(1, 0, second_plate);
+            plates.get_plate(0)->add_instance(0, 0, true);
+        } else {
+            m_plater->load_files(fixture.files, LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence,
+                                 false);
+            while (plates.get_plate_count() < fixture.plates)
+                plates.create_plate(true);
+            // Spread the objects evenly over the plates in a grid, then let
+            // the plate list assign each instance to the plate it sits on.
+            const ModelObjectPtrs& objects   = m_plater->model().objects;
+            const std::size_t      per_plate = (objects.size() + fixture.plates - 1) / fixture.plates;
+            const int              columns   = std::max(1, static_cast<int>(std::ceil(std::sqrt(double(per_plate)))));
+            for (std::size_t index = 0; index < objects.size(); ++index) {
+                const int           plate = static_cast<int>(index / per_plate);
+                const int           slot  = static_cast<int>(index % per_plate);
+                const BoundingBoxf3 bed   = plates.get_plate(plate)->get_bounding_box();
+                const double        dx = bed.size().x() / columns, dy = bed.size().y() / columns;
+                ModelInstance*      instance = objects[index]->instances.front();
+                instance->set_offset(Vec3d(bed.min.x() + dx * (slot % columns + 0.5), bed.min.y() + dy * (slot / columns + 0.5),
+                                           instance->get_offset().z()));
+                objects[index]->invalidate_bounding_box();
+            }
+            plates.reload_all_objects();
+        }
+        m_plater->canvas3D()->reload_scene(true, true);
+        const double load_ms = ms_between(start, Clock::now());
+        dialogs.Unregister();
+
+        std::size_t triangles = 0;
+        for (const ModelObject* object : m_plater->model().objects)
+            triangles += object->facets_count();
+        std::ostringstream per_plate;
+        for (int plate = 0; plate < plates.get_plate_count(); ++plate)
+            per_plate << (plate ? "," : "") << plates.get_plate(plate)->get_objects_on_this_plate().size();
+        std::cerr << "SAVECOST LOAD fixture=" << fixture.name << " objects=" << m_plater->model().objects.size()
+                  << " plates=" << plates.get_plate_count() << " per_plate=" << per_plate.str() << " triangles=" << triangles
+                  << " load_ms=" << load_ms << " dialogs=" << dialogs.count << '\n';
+    }
+
+    // Times one Plater::export_3mf call and the stages its progress callback reports.
+    void timed_export(const std::string& fixture, const char* kind, int run, const fs::path& path, SaveStrategy strategy)
+    {
+        static const char* const stage_names[] = {"open",           "content_types", "thumbnails",   "relations",  "models",
+                                                  "layer_range",    "support",       "custom_gcode", "print_config",
+                                                  "project_config", "config_file",   "slice_info",   "gcode",      "auxiliaries",
+                                                  "finish"};
+        std::vector<std::pair<int, Clock::time_point>> stages;
+        Export3mfProgressFn progress = [&stages](int stage, int, int, bool&) { stages.emplace_back(stage, Clock::now()); };
+        const Clock::time_point start  = Clock::now();
+        const int               result = m_plater->export_3mf(path, strategy, -1, progress);
+        const Clock::time_point end    = Clock::now();
+
+        boost::system::error_code error;
+        const auto bytes = fs::file_size(path, error);
+        // Time after a stage's callback, until the next callback, belongs to that stage.
+        std::vector<std::pair<std::string, double>> spans;
+        auto add = [&spans](const std::string& name, double ms) {
+            for (auto& span : spans)
+                if (span.first == name) {
+                    span.second += ms;
+                    return;
+                }
+            spans.emplace_back(name, ms);
+        };
+        add("pre", ms_between(start, stages.empty() ? end : stages.front().second));
+        for (std::size_t index = 0; index < stages.size(); ++index) {
+            const int stage = stages[index].first;
+            add(stage >= 0 && stage <= 14 ? stage_names[stage] : "stage" + std::to_string(stage),
+                ms_between(stages[index].second, index + 1 < stages.size() ? stages[index + 1].second : end));
+        }
+        std::ostringstream steps;
+        steps << std::fixed << std::setprecision(1);
+        for (std::size_t index = 0; index < spans.size(); ++index)
+            steps << (index ? "," : "") << spans[index].first << ':' << spans[index].second;
+        std::cerr << "SAVECOST RUN fixture=" << fixture << " kind=" << kind << " run=" << run
+                  << " ms=" << ms_between(start, end) << " bytes=" << (error ? 0 : bytes) << " result=" << result
+                  << " steps=" << steps.str() << '\n';
+        check(result >= 0 && !error && bytes > 0, std::string("save_cost_") + fixture + "_" + kind + "_written");
+    }
+
+    void queue_cost_fixture(const CostFixture& fixture)
+    {
+        const fs::path out = fs::path(m_state->save_cost_dir) / "out";
+        const int      warm = m_state->save_cost_warm;
+        auto self = shared_from_this();
+
+        m_steps.emplace_back([self](std::function<void()> done) {
+            self->check(self->m_plater->new_project(true, true) != wxID_CANCEL, "save_cost_new_project");
+            // Let the backup thread's removal of the previous project's files finish first.
+            self->poll_until([] { return false; }, 1000, [done](bool, Clock::time_point) { done(); });
+        });
+        m_steps.emplace_back([self, fixture](std::function<void()> done) {
+            self->load_cost_fixture(fixture);
+            done();
+        });
+        // Timings taken while the backup thread still writes the loaded meshes
+        // would include that contention, so wait for all mesh files first.
+        m_steps.emplace_back([self, fixture](std::function<void()> done) {
+            const Clock::time_point start = Clock::now();
+            self->poll_until([self] { return self->all_meshes_backed_up(); }, 1200000,
+                             [self, fixture, start, done](bool ok, Clock::time_point at) {
+                                 std::cerr << "SAVECOST MESHREADY fixture=" << fixture.name << " ok=" << ok
+                                           << " after_ms=" << ms_between(start, at) << '\n';
+                                 self->check(ok, "save_cost_" + fixture.name + "_meshes_backed_up");
+                                 self->poll_until([] { return false; }, 500, [done](bool, Clock::time_point) { done(); });
+                             });
+        });
+
+        auto queue_runs = [&](const char* kind, std::function<fs::path()> path, SaveStrategy strategy) {
+            for (int run = 0; run <= warm; ++run)
+                m_steps.emplace_back([self, fixture, kind, run, path, strategy](std::function<void()> done) {
+                    self->timed_export(fixture.name, kind, run, path(), strategy);
+                    done();
+                });
+        };
+
+        // Backup write, as MainFrame's backup callback issues it.
+        queue_runs("backup", [self] { return fs::path(self->m_plater->model().get_backup_path() + "/.3mf"); }, SaveStrategy::Backup);
+
+        // Crash-loss window: an edit that makes OrcaSlicer rewrite one object's
+        // mesh backup, until the rewritten file is in place. Renaming takes the
+        // same path as a mesh edit (save_object_mesh -> AddObject task) and
+        // names a new file, so its arrival is unambiguous.
+        m_steps.emplace_back([self, fixture](std::function<void()> done) {
+            ModelObject*            object = self->m_plater->model().objects.front();
+            const Clock::time_point edit   = Clock::now();
+            self->check(self->m_plater->rename_object(0, object->name + "-edited"), "save_cost_rename");
+            const double      edit_ms = ms_between(edit, Clock::now());
+            const std::string target  = self->mesh_backup_file(*object);
+            self->poll_until([target] { return fs::exists(target); }, 120000,
+                             [self, fixture, edit, edit_ms, done](bool ok, Clock::time_point at) {
+                                 std::cerr << "SAVECOST MESHLAG fixture=" << fixture.name << " trigger=rename ok=" << ok
+                                           << " edit_ms=" << edit_ms << " file_after_ms=" << ms_between(edit, at) << '\n';
+                                 done();
+                             });
+        });
+        // The same, triggered by save_object_mesh alone, as the move/rotate/scale
+        // of a part and the paint gizmos call it; the file is replaced by rename.
+        m_steps.emplace_back([self, fixture](std::function<void()> done) {
+            ModelObject*            object = self->m_plater->model().objects.front();
+            const std::string       target = self->mesh_backup_file(*object);
+            const ino_t             before = inode_of(target);
+            const Clock::time_point edit   = Clock::now();
+            Slic3r::save_object_mesh(*object);
+            const double edit_ms = ms_between(edit, Clock::now());
+            self->poll_until([target, before] { return inode_of(target) != 0 && inode_of(target) != before; }, 120000,
+                             [self, fixture, edit, edit_ms, done](bool ok, Clock::time_point at) {
+                                 std::cerr << "SAVECOST MESHLAG fixture=" << fixture.name << " trigger=save_object_mesh ok=" << ok
+                                           << " edit_ms=" << edit_ms << " file_after_ms=" << ms_between(edit, at) << '\n';
+                                 self->poll_until([] { return false; }, 500, [done](bool, Clock::time_point) { done(); });
+                             });
+        });
+
+        // Checkpoint: the flags OrcaWorkspaceAdapter::export_project_archive passes.
+        queue_runs("checkpoint", [out, fixture] { return out / (fixture.name + "-checkpoint.3mf"); },
+                   SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::ShareMesh | SaveStrategy::SkipAuxiliary);
+        m_steps.emplace_back([self, fixture, out](std::function<void()> done) {
+            OrcaWorkspaceAdapter    adapter(*self->m_plater);
+            const fs::path          path  = out / (fixture.name + "-adapter.3mf");
+            const Clock::time_point start = Clock::now();
+            const bool              ok    = adapter.export_project_archive(path.string()).succeeded();
+            boost::system::error_code error;
+            std::cerr << "SAVECOST RUN fixture=" << fixture.name << " kind=checkpoint_adapter run=0 ms="
+                      << ms_between(start, Clock::now()) << " bytes=" << fs::file_size(path, error) << " result=" << (ok ? 0 : -1)
+                      << '\n';
+            done();
+        });
+
+        // Full save: the flags Plater::save_project passes (not Silence, so the
+        // first run also makes this file the project's file).
+        queue_runs("full", [out, fixture] { return out / (fixture.name + "-full.3mf"); },
+                   SaveStrategy::SplitModel | SaveStrategy::ShareMesh);
+        // Plater::save_project itself, which adds its bookkeeping and clears the backup folder.
+        for (int run = 0; run < 3; ++run)
+            m_steps.emplace_back([self, fixture, out, run](std::function<void()> done) {
+                struct DialogProbe : wxModalDialogHook {
+                    int count{0};
+                    int Enter(wxDialog*) override { ++count; return wxID_CANCEL; }
+                } dialogs;
+                dialogs.Register();
+                const Clock::time_point start  = Clock::now();
+                const int               result = self->m_plater->save_project(false);
+                const double            ms     = ms_between(start, Clock::now());
+                dialogs.Unregister();
+                boost::system::error_code error;
+                std::cerr << "SAVECOST RUN fixture=" << fixture.name << " kind=save_project run=" << run << " ms=" << ms
+                          << " bytes=" << fs::file_size(out / (fixture.name + "-full.3mf"), error) << " result=" << result
+                          << " dialogs=" << dialogs.count << '\n';
+                self->check(dialogs.count == 0, "save_cost_save_project_no_dialog");
+                done();
+            });
+    }
+
+    void start_save_cost()
+    {
+        m_plater = m_app.plater();
+        fs::create_directories(fs::path(m_state->save_cost_dir) / "out");
+        std::cerr << std::fixed << std::setprecision(1);
+        std::cerr << "SAVECOST START dir=" << m_state->save_cost_dir << " warm=" << m_state->save_cost_warm
+                  << " threads=" << std::thread::hardware_concurrency() << '\n';
+        // Exporting renders thumbnails, which needs the canvas's GL state; the
+        // canvas initializes it while loading the first model.
+        auto self = shared_from_this();
+        m_steps.emplace_back([self](std::function<void()> done) {
+            self->load_cost_fixture(CostFixture{"tiny", {}, 2});
+            self->poll_until([self] { return self->m_plater->canvas3D()->is_initialized(); }, 30000,
+                             [self, done](bool ok, Clock::time_point) {
+                                 if (!ok) {
+                                     self->fail("the 3D canvas did not initialize OpenGL");
+                                     return;
+                                 }
+                                 done();
+                             });
+        });
+        for (const CostFixture& fixture : cost_fixtures())
+            queue_cost_fixture(fixture);
+        run_next_step();
+    }
+
     static constexpr std::size_t invalid_index = static_cast<std::size_t>(-1);

     GUI_App&                              m_app;
@@ -813,6 +1168,8 @@ private:
     int                                   m_failures{0};
     bool                                  m_finished{false};
     std::unique_ptr<CanvasPresentationController> m_manual_controller;
+    std::deque<std::function<void(std::function<void()>)>> m_steps;
+    std::unique_ptr<wxTimer>                               m_poll;
