// ---- Checkpoint-storage spike (--ckpt <dir>) ----
// Runs scripted editing sessions. At each checkpoint it writes a full
// project archive and a backup-style checkpoint: OrcaSlicer's small
// backup archive plus hard links to the backup folder's mesh files, which
// OrcaSlicer replaces by rename and never rewrites in place. Sizes are
// analysed offline by tests/workspace/ckpt_storage/analyze.py. One line
// per event, prefixed "CKPT", for grep.
struct CkptProject
{
    std::string              name;
    std::vector<std::string> files;
};

std::vector<CkptProject> ckpt_projects() const
{
    const fs::path dir(m_state->ckpt_dir);
    std::vector<CkptProject> chosen;
    for (const char* name : {"small", "medium", "large"}) {
        const auto& wanted = m_state->ckpt_projects;
        if (!wanted.empty() && std::find(wanted.begin(), wanted.end(), name) == wanted.end())
            continue;
        CkptProject project{name, {}};
        if (fs::is_directory(dir / name))
            for (const fs::directory_entry& entry : fs::directory_iterator(dir / name))
                if (entry.path().extension() == ".stl")
                    project.files.emplace_back(entry.path().string());
        std::sort(project.files.begin(), project.files.end());
        if (project.files.empty())
            std::cerr << "CKPT SKIP project=" << name << " reason=no_files\n";
        else
            chosen.emplace_back(project);
    }
    return chosen;
}

bool ckpt_wants(const std::string& session) const
{
    const auto& wanted = m_state->ckpt_sessions;
    return wanted.empty() || std::find(wanted.begin(), wanted.end(), session) != wanted.end();
}

fs::path backup_objects_dir() { return fs::path(m_plater->model().get_backup_path()) / "3D" / "Objects"; }

// Every finished mesh file in the backup folder, by file name.
std::map<std::string, ino_t> backup_mesh_inodes()
{
    std::map<std::string, ino_t> files;
    boost::system::error_code    error;
    for (fs::directory_iterator it(backup_objects_dir(), error), end; !error && it != end; it.increment(error))
        if (it->path().extension() == ".model")
            files[it->path().filename().string()] = inode_of(it->path().string());
    return files;
}

bool backup_has_tmp()
{
    boost::system::error_code error;
    for (fs::directory_iterator it(backup_objects_dir(), error), end; !error && it != end; it.increment(error))
        if (it->path().extension() == ".tmp")
            return true;
    return false;
}

ObjectId ck_id(std::size_t index) const
{
    return ObjectId(m_ck_ws->snapshot().session, m_plater->model().objects[index]->id().id);
}

std::size_t largest_object() const
{
    const ModelObjectPtrs& objects = m_plater->model().objects;
    std::size_t            best    = 0;
    for (std::size_t index = 1; index < objects.size(); ++index)
        if (objects[index]->facets_count() > objects[best]->facets_count())
            best = index;
    return best;
}

static std::string paint_summary(const FacetsAnnotation& paint)
{
    const auto& data = paint.get_data();
    std::size_t set  = 0;
    for (bool bit : data.bitstream)
        set += bit;
    return std::to_string(data.triangles_to_split.size()) + "/" + std::to_string(data.bitstream.size()) + "/" +
           std::to_string(set);
}

// What the round trip compares: objects, meshes, placement, plates, paint,
// and every setting in force.
std::vector<std::string> describe_state()
{
    std::vector<std::string> lines;
    Model&                   model  = m_plater->model();
    PartPlateList&           plates = m_plater->get_partplate_list();
    lines.emplace_back("objects " + std::to_string(model.objects.size()) + " plates " +
                       std::to_string(plates.get_plate_count()));
    for (std::size_t index = 0; index < model.objects.size(); ++index) {
        const ModelObject& object = *model.objects[index];
        std::ostringstream line;
        line << std::fixed << std::setprecision(3) << "object name=" << object.name << " facets=" << object.facets_count()
             << " volumes=" << object.volumes.size() << " instances=" << object.instances.size()
             << " plate=" << plates.find_instance_belongs(static_cast<int>(index), 0);
        for (const ModelInstance* instance : object.instances) {
            const Vec3d offset = instance->get_offset(), rotation = instance->get_rotation(),
                        scale = instance->get_scaling_factor();
            line << " at=" << offset.x() << "," << offset.y() << "," << offset.z() << " rot=" << rotation.x() << ","
                 << rotation.y() << "," << rotation.z() << " scale=" << scale.x() << "," << scale.y() << "," << scale.z();
        }
        for (const ModelVolume* volume : object.volumes)
            line << " part=" << volume->name << ":" << volume->mesh().its.indices.size()
                 << ":support=" << paint_summary(volume->supported_facets);
        lines.emplace_back(line.str());
    }
    const DynamicPrintConfig config = wxGetApp().preset_bundle->full_config_secure();
    for (const std::string& key : config.keys())
        lines.emplace_back("config " + key + "=" + config.opt_serialize(key));
    return lines;
}

static void write_lines(const fs::path& path, const std::vector<std::string>& lines)
{
    std::ostringstream text;
    for (const std::string& line : lines)
        text << line << '\n';
    save_string_file(path.string(), text.str());
}

int compare_states(const std::string& what, const std::vector<std::string>& before, const std::vector<std::string>& after)
{
    int differences = 0;
    for (std::size_t index = 0; index < std::max(before.size(), after.size()); ++index) {
        const std::string left  = index < before.size() ? before[index] : "<missing>";
        const std::string right = index < after.size() ? after[index] : "<missing>";
        if (left == right)
            continue;
        if (++differences <= 20)
            std::cerr << "CKPT DIFF " << what << "\n  before: " << left << "\n  after:  " << right << '\n';
    }
    std::cerr << "CKPT COMPARE " << what << " lines=" << before.size() << "/" << after.size() << " differences=" << differences
              << '\n';
    return differences;
}

// Waits until the backup folder holds a finished mesh file for every
// object and each of `expected` has been replaced, then logs how long it took.
void settle(const std::string& label, std::map<std::string, ino_t> expected, double timeout_ms, std::function<void(bool)> then)
{
    const Clock::time_point start = Clock::now();
    auto                    self  = shared_from_this();
    poll_until(
        [self, expected] {
            for (const ModelObject* object : self->m_plater->model().objects)
                if (!fs::exists(self->mesh_backup_file(*object)))
                    return false;
            for (const auto& [name, before] : expected) {
                const ino_t now = inode_of((self->backup_objects_dir() / name).string());
                if (now == 0 || now == before)
                    return false;
            }
            return !self->backup_has_tmp();
        },
        timeout_ms,
        [self, label, start, then](bool ok, Clock::time_point at) {
            std::cerr << "CKPT SETTLE project=" << self->m_ck_project << " session=" << self->m_ck_session << " after=" << label
                      << " ok=" << ok << " ms=" << ms_between(start, at) << '\n';
            then(ok);
        });
}

std::string mesh_file_name(const ModelObject& object) { return fs::path(mesh_backup_file(object)).filename().string(); }

// One edit through the workspace interface. Returns the mesh files the
// edit must make OrcaSlicer rewrite, by their inode before the edit.
std::map<std::string, ino_t> ck_edit(const std::string& kind, int n)
{
    struct DialogProbe : wxModalDialogHook {
        int count{0};
        int Enter(wxDialog*) override { ++count; return wxID_CANCEL; }
    } dialogs;
    dialogs.Register();
    std::map<std::string, ino_t> expected;
    const auto                   inodes = backup_mesh_inodes();
    Model&                       model  = m_plater->model();
    const std::size_t            count  = model.objects.size();
    const std::size_t            index  = static_cast<std::size_t>(n) % count;
    bool                         ok     = false;
    std::string                  detail;
    if (kind == "move" || kind == "rotate" || kind == "scale") {
        PlacementRequest request;
        if (kind == "move") {
            const Vec3d at = model.objects[index]->instances.front()->get_offset();
            request.position = std::array<double, 2>{at.x() + (n % 2 ? 4.0 : -4.0), at.y() + (n % 3 ? 3.0 : -3.0)};
        } else if (kind == "rotate")
            request.rotate = Vec3{0, 0, 15};
        else {
            const double factor = n % 2 ? 1.05 : 1 / 1.05;
            request.scale = Vec3{factor, factor, factor};
        }
        PlacementResult result;
        ok = m_ck_ws->place_object(ck_id(index), request, "", result).succeeded();
    } else if (kind == "setting") {
        static const std::vector<std::pair<std::string, std::vector<std::string>>> keys{
            {"sparse_infill_density", {"15%", "25%"}}, {"wall_loops", {"3", "2"}}, {"layer_height", {"0.16", "0.2"}}};
        const auto& [key, values] = keys[static_cast<std::size_t>(n) % keys.size()];
        SettingsPatch patch;
        patch.changes[key] = values[static_cast<std::size_t>(n / keys.size()) % values.size()];
        const SettingsPreview preview = m_ck_ws->preview_settings(patch);
        SettingsPreview       applied;
        ok     = preview.valid && m_ck_ws->apply_settings(patch, settings_confirmation(preview), applied).succeeded();
        detail = key + "=" + patch.changes[key];
    } else if (kind == "plate") {
        const WorkspaceSnapshot snapshot = m_ck_ws->snapshot();
        const ObjectId          id       = ck_id(index);
        std::size_t             current  = 0;
        for (std::size_t plate = 0; plate < snapshot.plates.size(); ++plate)
            for (const WorkspaceObject& object : snapshot.plates[plate].objects)
                if (object.id == id)
                    current = plate;
        LayoutRequest request;
        LayoutObject  row;
        row.id    = id;
        row.plate = snapshot.plates[(current + 1) % snapshot.plates.size()].id;
        request.objects.push_back(row);
        LayoutResult result;
        ok     = m_ck_ws->lay_out(request, "", result).succeeded();
        detail = "to_plate=" + std::to_string((current + 1) % snapshot.plates.size());
    } else if (kind == "cut") {
        const std::size_t target = largest_object();
        DivideRequest     request;
        const Vec3d       center = model.objects[target]->instance_bounding_box(0).center();
        request.point            = Vec3{center.x(), center.y(), center.z()};
        DivideResult result;
        ok     = m_ck_ws->divide_object(ck_id(target), request, result).succeeded();
        detail = "pieces=" + std::to_string(result.pieces.size());
    } else if (kind == "repair") {
        // The last object: the mesh session imports an open mesh just before.
        const std::size_t target = count - 1;
        const std::string file   = mesh_file_name(*model.objects[target]);
        RepairResult      result;
        ok     = m_ck_ws->repair_object(ck_id(target), result).succeeded();
        detail = "changed=" + std::to_string(result.changed) + " open_edges=" + std::to_string(result.open_edges_before) + "->" +
                 std::to_string(result.open_edges_after) + " facets=" + std::to_string(result.facets_before) + "->" +
                 std::to_string(result.facets_after);
        if (result.changed && inodes.count(file))
            expected[file] = inodes.at(file);
    } else if (kind == "delete") {
        DeleteItem item;
        item.object = ck_id(index);
        ok          = m_ck_ws->delete_items({item}).succeeded();
    } else if (kind == "import") {
        ImportRequest request;
        request.path = (fs::path(m_state->ckpt_dir) / "extra" / "open.stl").string();
        std::vector<LoadDecision> decisions;
        std::vector<ObjectId>     added;
        ok     = m_ck_ws->import_objects(request, decisions, added).succeeded();
        detail = "added=" + std::to_string(added.size());
    } else if (kind == "merge") {
        ObjectId merged;
        ok = count >= 2 && m_ck_ws->merge_objects({ck_id(0), ck_id(1)}, merged).succeeded();
    } else if (kind == "paint") {
        const std::size_t target = largest_object();
        ModelObject&      object = *model.objects[target];
        const std::string file   = mesh_file_name(object);
        const int         facets = static_cast<int>(model_parts(object).front()->mesh().its.indices.size());
        RegionRecord      record;
        record.id          = "r" + std::to_string(n);
        record.kind        = "support";
        record.object      = object.id().id;
        record.object_name = object.name;
        RegionArtifact paint;
        paint.type   = "paint";
        paint.target = "support";
        paint.state  = "enforcer";
        // Each stroke paints a different 2% of the triangles.
        for (int facet = (n * facets) / 10; facet < (n * facets) / 10 + facets / 50 && facet < facets; ++facet)
            paint.facets.push_back(facet);
        record.artifacts.push_back(paint);
        std::vector<RegionRecord> applied;
        ok     = m_ck_ws->apply_regions({record}, {}, applied).succeeded();
        detail = "facets=" + std::to_string(paint.facets.size()) + " of " + std::to_string(facets);
        if (inodes.count(file))
            expected[file] = inodes.at(file);
    }
    dialogs.Unregister();
    std::cerr << "CKPT EDIT project=" << m_ck_project << " session=" << m_ck_session << " n=" << n << " kind=" << kind
              << " ok=" << ok << " objects=" << model.objects.size() << " dialogs=" << dialogs.count << (detail.empty() ? "" : " ")
              << detail << '\n';
    check(ok, "ckpt_edit_" + kind);
    return expected;
}

// Writes both kinds of checkpoint and times the main-thread part of each.
void ck_checkpoint()
{
    char name[16];
    std::snprintf(name, sizeof(name), "c%02d", m_ck_index++);
    const fs::path bk = m_ck_run / "bk" / name;
    fs::create_directories(bk / "3D" / "Objects");
    fs::create_directories(m_ck_run / "full");
    fs::create_directories(m_ck_run / "state");

    const Clock::time_point t0        = Clock::now();
    const int               bk_result = m_plater->export_3mf(bk / ".3mf", SaveStrategy::Backup | SaveStrategy::Silence);
    const Clock::time_point t1        = Clock::now();
    std::size_t             links = 0, link_bytes = 0;
    std::ostringstream      manifest;
    for (const ModelObject* object : m_plater->model().objects) {
        const fs::path            source(mesh_backup_file(*object));
        boost::system::error_code error;
        fs::create_hard_link(source, bk / "3D" / "Objects" / source.filename(), error);
        if (!error) {
            ++links;
            link_bytes += fs::file_size(source, error);
        }
        manifest << source.filename().string() << ' ' << inode_of(source.string()) << ' ' << fs::file_size(source, error) << '\n';
    }
    const Clock::time_point t2 = Clock::now();
    save_string_file((bk / "manifest.txt").string(), manifest.str());

    const fs::path          full        = m_ck_run / "full" / (std::string(name) + ".3mf");
    const Clock::time_point t3          = Clock::now();
    const int               full_result = m_plater->export_3mf(full, SaveStrategy::Silence | SaveStrategy::SplitModel |
                                                                       SaveStrategy::ShareMesh | SaveStrategy::SkipAuxiliary);
    const Clock::time_point t4          = Clock::now();
    write_lines(m_ck_run / "state" / (std::string(name) + ".txt"), describe_state());

    // What changed in the backup folder since the previous checkpoint.
    const auto  now     = backup_mesh_inodes();
    std::size_t changed = 0, added = 0, removed = 0;
    for (const auto& [file, inode] : now) {
        const auto previous = m_ck_inodes.find(file);
        if (previous == m_ck_inodes.end())
            ++added;
        else if (previous->second != inode)
            ++changed;
    }
    for (const auto& [file, inode] : m_ck_inodes)
        removed += now.count(file) == 0;
    m_ck_inodes = now;

    boost::system::error_code error;
    std::cerr << "CKPT CHECKPOINT project=" << m_ck_project << " session=" << m_ck_session << " name=" << name
              << " objects=" << m_plater->model().objects.size() << " bk_ms=" << ms_between(t0, t1)
              << " bk_bytes=" << fs::file_size(bk / ".3mf", error) << " link_ms=" << ms_between(t1, t2) << " links=" << links
              << " link_bytes=" << link_bytes << " full_ms=" << ms_between(t3, t4)
              << " full_bytes=" << fs::file_size(full, error) << " files_added=" << added << " files_changed=" << changed
              << " files_removed=" << removed << " bk_result=" << bk_result << " full_result=" << full_result << '\n';
    check(bk_result >= 0 && full_result >= 0 && links == m_plater->model().objects.size(), "ckpt_checkpoint_written");
}

void ck_queue_fresh_project(const CkptProject& project, const std::string& session)
{
    auto self = shared_from_this();
    m_steps.emplace_back([self, project, session](std::function<void()> done) {
        self->m_ck_project = project.name;
        self->m_ck_session = session;
        self->m_ck_index   = 0;
        self->m_ck_inodes.clear();
        self->m_ck_run = fs::path(self->m_state->ckpt_dir) / "out" / (project.name + "-" + session);
        fs::remove_all(self->m_ck_run);
        fs::create_directories(self->m_ck_run);
        self->check(self->m_plater->new_project(true, true) != wxID_CANCEL, "ckpt_new_project");
        self->poll_until([] { return false; }, 1000, [done](bool, Clock::time_point) { done(); });
    });
    m_steps.emplace_back([self, project](std::function<void()> done) {
        self->load_cost_fixture(CostFixture{project.name, project.files, 2});
        self->m_ck_ws = std::make_unique<OrcaWorkspaceAdapter>(*self->m_plater);
        done();
    });
    m_steps.emplace_back([self](std::function<void()> done) {
        self->settle("load", {}, 600000, [self, done](bool ok) {
            self->check(ok, "ckpt_meshes_backed_up_after_load");
            done();
        });
    });
}

// Queues edits then a checkpoint. `pause_ms` waits before settling, so a
// write the edit was not expected to cause has time to show up.
void ck_queue_edits(std::vector<std::pair<std::string, int>> edits, bool checkpoint_after, double pause_ms = 0)
{
    auto self     = shared_from_this();
    auto expected = std::make_shared<std::map<std::string, ino_t>>();
    for (const auto& [kind, n] : edits)
        m_steps.emplace_back([self, expected, kind = kind, n = n](std::function<void()> done) {
            for (const auto& entry : self->ck_edit(kind, n))
                expected->insert(entry);
            done();
        });
    m_steps.emplace_back([self, expected, edits, pause_ms](std::function<void()> done) {
        const std::string label = edits.empty() ? std::string("none") : edits.back().first;
        auto              run   = [self, expected, label, done] {
            self->settle(label, *expected, 60000, [self, expected, label, done](bool ok) {
                if (ok || expected->empty() || label != "paint") {
                    done();
                    return;
                }
                // OrcaSlicer's paint tools queue the object's backup
                // themselves; do what they do and wait again.
                std::cerr << "CKPT PAINT_NOT_BACKED_UP project=" << self->m_ck_project << " session=" << self->m_ck_session
                          << '\n';
                Slic3r::save_object_mesh(*self->m_plater->model().objects[self->largest_object()]);
                self->settle("paint_after_save_object_mesh", *expected, 60000, [done](bool) { done(); });
            });
        };
        if (pause_ms > 0)
            self->poll_until([] { return false; }, pause_ms, [run](bool, Clock::time_point) { run(); });
        else
            run();
    });
    if (checkpoint_after)
        m_steps.emplace_back([self](std::function<void()> done) {
            self->ck_checkpoint();
            done();
        });
}

void ck_queue_session(const CkptProject& project, const std::string& session)
{
    ck_queue_fresh_project(project, session);
    ck_queue_edits({}, true); // c00: the project as opened
    static const std::vector<std::string> layout{"move", "rotate", "scale", "setting", "plate"};
    if (session == "layout") {
        for (int group = 0; group < 10; ++group) {
            std::vector<std::pair<std::string, int>> edits;
            for (int n = group * 4; n < group * 4 + 4; ++n)
                edits.emplace_back(layout[static_cast<std::size_t>(n) % layout.size()], n);
            // Long enough for a 2,000,000-triangle mesh write that nobody expects.
            ck_queue_edits(edits, true, 9000);
        }
    } else if (session == "mesh") {
        for (const char* kind : {"cut", "delete", "import", "repair", "merge"})
            ck_queue_edits({{kind, 1}}, true);
    } else if (session == "paint") {
        for (int stroke = 0; stroke < 5; ++stroke)
            ck_queue_edits({{"paint", stroke}}, true);
    } else if (session == "mixed") {
        std::vector<std::pair<std::string, int>> edits;
        for (int n = 0; n < 30; ++n) {
            edits.emplace_back(n == 7 ? "cut" : n == 16 ? "paint" : n == 25 ? "import" : layout[static_cast<std::size_t>(n) % layout.size()], n);
            if (edits.size() == 3) {
                ck_queue_edits(edits, true, 4000);
                edits.clear();
            }
        }
    }
}

// Question 2: is an unchanged object's mesh file the same bytes from one write to the next?
void ck_queue_identity(const CkptProject& project)
{
    ck_queue_fresh_project(project, "identity");
    auto self = shared_from_this();
    auto link_all = [self](const std::string& name) {
        const fs::path dir = self->m_ck_run / "q2" / name;
        fs::create_directories(dir);
        for (const ModelObject* object : self->m_plater->model().objects) {
            const fs::path            source(self->mesh_backup_file(*object));
            boost::system::error_code error;
            fs::create_hard_link(source, dir / source.filename(), error);
        }
    };
    auto export_full = [self](const std::string& name) {
        fs::create_directories(self->m_ck_run / "q2");
        self->m_plater->export_3mf(self->m_ck_run / "q2" / (name + ".3mf"),
                                   SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::ShareMesh | SaveStrategy::SkipAuxiliary);
    };
