// Question 4: take a checkpoint, then destroy what a backup-style
// checkpoint could depend on, rebuild a project from the store alone and load it.
void ck_queue_roundtrip(const CkptProject& project)
{
    ck_queue_fresh_project(project, "roundtrip");
    // Some state worth restoring: paint, a setting, an object on the other plate.
    ck_queue_edits({{"paint", 1}, {"setting", 0}, {"plate", 2}, {"rotate", 3}}, true);
    auto self   = shared_from_this();
    auto before = std::make_shared<std::vector<std::string>>();
    auto rt     = std::make_shared<fs::path>();
    m_steps.emplace_back([self, before, rt](std::function<void()> done) {
        *before = self->describe_state();
        *rt     = self->m_ck_run / "rt";
        fs::create_directories(*rt);
        write_lines(*rt / "before.txt", *before);
        // Give the project a file, as a person's first save does.
        self->check(self->m_plater->export_3mf(*rt / "project.3mf", SaveStrategy::SplitModel | SaveStrategy::ShareMesh) >= 0,
                    "ckpt_rt_first_save");
        done();
    });
    // The three events: change a mesh, delete an object, save in full.
    ck_queue_edits({{"cut", 0}, {"delete", 3}}, false);
    m_steps.emplace_back([self, rt](std::function<void()> done) {
        const auto files_before = self->backup_mesh_inodes().size();
        const int  result       = self->m_plater->save_project(false);
        self->poll_until([] { return false; }, 2000, [self, rt, files_before, result, done](bool, Clock::time_point) {
            std::size_t intact = 0, total = 0;
            std::ifstream manifest((self->m_ck_run / "bk" / "c00" / "manifest.txt").string());
            for (std::string file, inode, size; manifest >> file >> inode >> size;) {
                ++total;
                boost::system::error_code error;
                const fs::path            linked = self->m_ck_run / "bk" / "c00" / "3D" / "Objects" / file;
                intact += std::to_string(inode_of(linked.string())) == inode && std::to_string(fs::file_size(linked, error)) == size;
            }
            std::cerr << "CKPT RT_DESTROYED save_result=" << result << " backup_files_before=" << files_before
                      << " backup_files_after=" << self->backup_mesh_inodes().size() << " store_links_intact=" << intact << "/"
                      << total << '\n';
            done();
        });
    });
    // Way 1: OrcaSlicer's crash-restore load, from a scratch copy of the checkpoint.
    m_steps.emplace_back([self, before, rt](std::function<void()> done) {
        const fs::path scratch = *rt / "scratch";
        fs::remove_all(scratch);
        fs::create_directories(scratch / "3D" / "Objects");
        const fs::path bk = self->m_ck_run / "bk" / "c00";
        fs::copy_file(bk / ".3mf", scratch / ".3mf");
        for (fs::directory_iterator it(bk / "3D" / "Objects"), end; it != end; ++it)
            fs::copy_file(it->path(), scratch / "3D" / "Objects" / it->path().filename());
        struct DialogProbe : wxModalDialogHook {
            int count{0};
            int Enter(wxDialog*) override { ++count; return wxID_CANCEL; }
        } dialogs;
        dialogs.Register();
        const Clock::time_point start = Clock::now();
        self->m_plater->reset();
        const auto loaded = self->m_plater->load_files(std::vector<fs::path>{scratch / ".3mf", *rt / "project.3mf"},
                                                       LoadStrategy::LoadModel | LoadStrategy::LoadConfig | LoadStrategy::Restore, false);
        const double ms = ms_between(start, Clock::now());
        dialogs.Unregister();
        const auto after = self->describe_state();
        write_lines(*rt / "after-restore.txt", after);
        std::cerr << "CKPT RT_LOAD way=restore ms=" << ms << " loaded=" << loaded.size() << " dialogs=" << dialogs.count
                  << " backup_path=" << self->m_plater->model().get_backup_path() << '\n';
        self->check(self->compare_states("restore", *before, after) == 0, "ckpt_rt_restore_matches");
        done();
    });
    // Control: the full-copy checkpoint, loaded as an ordinary project.
    m_steps.emplace_back([self, before, rt](std::function<void()> done) {
        struct DialogProbe : wxModalDialogHook {
            int count{0};
            int Enter(wxDialog*) override { ++count; return wxID_CANCEL; }
        } dialogs;
        dialogs.Register();
        const Clock::time_point start = Clock::now();
        self->m_plater->reset();
        const auto loaded = self->m_plater->load_files(std::vector<fs::path>{self->m_ck_run / "full" / "c00.3mf"},
                                                       LoadStrategy::LoadModel | LoadStrategy::LoadConfig | LoadStrategy::Silence, false);
        const double ms = ms_between(start, Clock::now());
        dialogs.Unregister();
        const auto after = self->describe_state();
        write_lines(*rt / "after-full.txt", after);
        std::cerr << "CKPT RT_LOAD way=full ms=" << ms << " loaded=" << loaded.size() << " dialogs=" << dialogs.count << '\n';
        self->check(self->compare_states("full", *before, after) == 0, "ckpt_rt_full_matches");
        done();
    });
}

void start_ckpt()
{
    m_plater = m_app.plater();
    std::cerr << std::fixed << std::setprecision(1);
    std::cerr << "CKPT START dir=" << m_state->ckpt_dir << '\n';
    auto self = shared_from_this();
    m_steps.emplace_back([self](std::function<void()> done) {
        self->load_cost_fixture(CostFixture{"tiny", {}, 2});
        self->poll_until([self] { return self->m_plater->canvas3D()->is_initialized(); }, 30000,
                         [self, done](bool ok, Clock::time_point) {
                             if (!ok) {
                                 self->fail("the 3D canvas did not initialize OpenGL");
                                 return;
                             }
                             done();
                         });
    });
    for (const CkptProject& project : ckpt_projects()) {
        for (const char* session : {"layout", "mesh", "paint", "mixed"})
            if (ckpt_wants(session))
                ck_queue_session(project, session);
        if (project.name == "medium" && ckpt_wants("identity"))
            ck_queue_identity(project);
        if (project.name == "medium" && ckpt_wants("roundtrip"))
            ck_queue_roundtrip(project);
    }
    m_steps.emplace_back([self](std::function<void()> done) {
        self->m_ck_ws.reset();
        done();
    });
    run_next_step();
}

