#!/usr/bin/env python3
"""Checkpoint-storage spike: how much disk each storage scheme needs.

Reads <scratch>/out/<project>-<session>/ as the --ckpt probe left it:
  full/cNN.3mf              a full project archive per checkpoint
  bk/cNN/.3mf               OrcaSlicer's small backup archive per checkpoint
  bk/cNN/3D/Objects/*.model hard links to the backup folder's mesh files
and prints, per session and scheme, the bytes each checkpoint adds to a
store that keeps every distinct blob once, and the store's total.

Usage: analyze.py <scratch dir> [--q2]"""
import hashlib, os, sys, zipfile
from collections import OrderedDict

MANIFEST_ENTRY = 64  # bytes a store spends per referenced blob: a hash and a name


def sha(data):
    return hashlib.sha256(data).hexdigest()


def inner_entries(path):
    """A backup mesh file is itself a zip; return {entry name: (uncompressed sha, compressed size)}."""
    with zipfile.ZipFile(path) as z:
        return {i.filename: (sha(z.read(i.filename)), i.compress_size) for i in z.infolist()}


def checkpoints(run):
    names = sorted(n for n in os.listdir(os.path.join(run, "full")) if n.endswith(".3mf"))
    return [n[:-4] for n in names]


def full_copy(run, names):
    rows = []
    for n in names:
        size = os.path.getsize(os.path.join(run, "full", n + ".3mf"))
        rows.append((n, size))
    return rows


def split_afterwards(run, names):
    """Full archive taken apart: each entry stored once, keyed by its uncompressed content."""
    store, rows = {}, []
    for n in names:
        added = 0
        with zipfile.ZipFile(os.path.join(run, "full", n + ".3mf")) as z:
            infos = z.infolist()
            for i in infos:
                key = sha(z.read(i.filename))
                if key not in store:
                    store[key] = i.compress_size
                    added += i.compress_size
        added += MANIFEST_ENTRY * len(infos)
        rows.append((n, added))
    return rows


def backup_style(run, names, key_mode):
    """Small archive per checkpoint, plus each mesh file once.
    key_mode: 'inode' (what hard links give for free), 'file' (whole-file bytes),
    'content' (the uncompressed mesh inside the file)."""
    store, rows = {}, []
    for n in names:
        d = os.path.join(run, "bk", n)
        added = os.path.getsize(os.path.join(d, ".3mf"))
        objs = os.path.join(d, "3D", "Objects")
        files = sorted(os.listdir(objs)) if os.path.isdir(objs) else []
        for f in files:
            p = os.path.join(objs, f)
            if key_mode == "inode":
                key = os.stat(p).st_ino
            elif key_mode == "file":
                key = sha(open(p, "rb").read())
            else:
                key = tuple(sorted(v[0] for v in inner_entries(p).values()))
            if key not in store:
                store[key] = os.path.getsize(p)
                added += store[key]
        added += MANIFEST_ENTRY * len(files)
        rows.append((n, added))
    return rows


def summarize(scratch):
    out = os.path.join(scratch, "out")
    print("| Project | Session | Checkpoints | Scheme | First checkpoint | Later checkpoints: median | Later: largest | Total |")
    print("|---|---|---:|---|---:|---:|---:|---:|")
    for run_name in sorted(os.listdir(out)):
        run = os.path.join(out, run_name)
        if not os.path.isdir(os.path.join(run, "full")) or not os.path.isdir(os.path.join(run, "bk")):
            continue
        project, session = run_name.split("-", 1)
        names = checkpoints(run)
        if not names:
            continue
        schemes = OrderedDict()
        schemes["full copy"] = full_copy(run, names)
        schemes["split afterwards"] = split_afterwards(run, names)
        schemes["backup-style"] = backup_style(run, names, "content")
        schemes["backup-style, whole-file key"] = backup_style(run, names, "file")
        for scheme, rows in schemes.items():
            later = sorted(r[1] for r in rows[1:]) or [0]
            print(f"| {project} | {session} | {len(rows)} | {scheme} | {fmt(rows[0][1])} | {fmt(later[len(later) // 2])} "
                  f"| {fmt(later[-1])} | {fmt(sum(r[1] for r in rows))} |")
        if "-v" in sys.argv:
            for scheme, rows in schemes.items():
                print("   ", scheme, " ".join(f"{n}:{fmt(b)}" for n, b in rows))


def fmt(n):
    for unit, size in (("GB", 1e9), ("MB", 1e6), ("KB", 1e3)):
        if n >= size:
            return f"{n / size:.2f} {unit}" if n < 10 * size else f"{n / size:.1f} {unit}"
    return f"{n} B"


def q2(scratch):
    """Byte identity of unchanged objects' meshes, backup files and full archives."""
    base = os.path.join(scratch, "out", "medium-identity", "q2")
    print("\n## Backup mesh files (b0 load, b1 after save_object_mesh on the first object, b2 after renaming the second, b3 after an import, b4 after deleting the first)")
    snaps = sorted(d for d in os.listdir(base) if d.startswith("b"))
    files = {s: sorted(os.listdir(os.path.join(base, s))) for s in snaps}
    for s in snaps:
        print(f"  {s}: {len(files[s])} files")
    for a, b in zip(snaps, snaps[1:]):
        same_file = same_inner = differ = only = 0
        notes = []
        for f in files[a]:
            pa, pb = os.path.join(base, a, f), os.path.join(base, b, f)
            if not os.path.exists(pb):
                only += 1
                continue
            ba, bb = open(pa, "rb").read(), open(pb, "rb").read()
            ia, ib = inner_entries(pa), inner_entries(pb)
            if ba == bb:
                same_file += 1
            elif {k: v[0] for k, v in ia.items()} == {k: v[0] for k, v in ib.items()}:
                same_inner += 1
                notes.append(f"{f}: file bytes differ, inner mesh identical; inode {'same' if os.stat(pa).st_ino == os.stat(pb).st_ino else 'new'}")
            else:
                differ += 1
                notes.append(f"{f}: inner mesh differs")
        print(f"  {a}->{b}: identical files {same_file}, same mesh in different file bytes {same_inner}, different mesh {differ}, gone {only}")
        for n in notes:
            print("    ", n)
    # A renamed object: compare the old and new file's inner mesh, ignoring the entry name.
    print("\n## Full archives (f0, f1 no change, f2 after rename, f3 after import, f4 after deleting the first object)")
    arch = sorted(f for f in os.listdir(base) if f.startswith("f") and f.endswith(".3mf"))
    def entries(p):
        with zipfile.ZipFile(p) as z:
            return {i.filename: (sha(z.read(i.filename)), i.compress_size, i.date_time) for i in z.infolist()}
    ents = {a: entries(os.path.join(base, a)) for a in arch}
    for a, b in zip(arch, arch[1:]):
        ea, eb = ents[a], ents[b]
        meshes = [k for k in ea if k.startswith("3D/Objects/")]
        same = sum(1 for k in meshes if k in eb and eb[k][0] == ea[k][0])
        changed = [k for k in meshes if k in eb and eb[k][0] != ea[k][0]]
        gone = [k for k in meshes if k not in eb]
        other = [k for k in ea if not k.startswith("3D/Objects/") and k in eb and eb[k][0] != ea[k][0]]
        fb = open(os.path.join(base, a), "rb").read() == open(os.path.join(base, b), "rb").read()
        print(f"  {a}->{b}: archive bytes identical {fb}; mesh entries same {same}/{len(meshes)}, changed {len(changed)}, gone {len(gone)}; other entries changed: {other}")
        for k in changed:
            print("     changed:", k)
    # Backup file inner mesh vs the full archive's entry for the same object.
    b0 = os.path.join(base, "b0")
    f0 = ents[arch[0]]
    match = 0
    for f in files["b0"]:
        inner = inner_entries(os.path.join(b0, f))
        for k, v in inner.items():
            match += f0.get(k, (None,))[0] == v[0]
    print(f"\n  backup file inner mesh == full archive entry of the same name: {match}/{len(files['b0'])}")


if __name__ == "__main__":
    scratch = sys.argv[1]
    if "--q2" in sys.argv:
        q2(scratch)
    else:
        summarize(scratch)

